<script setup lang="ts">
import {computed,onMounted,ref} from 'vue';import {Download,Upload,Save,Trash2} from 'lucide-vue-next';import Modal from '../../components/Modal.vue';import {detail,importAccounts,remove,update,type Account} from '../../api/endpoints';import {download,message} from '../../api/client'
type Mode='import'|'create'|'edit'|'delete'|'export';const props=defineProps<{mode:Mode;item?:Account;query:string;realmFilter:string}>();const emit=defineEmits<{close:[];saved:[text:string]}>();const labels:Record<Mode,string>={import:'导入账号',create:'新建账号',edit:'编辑账号',delete:'删除账号',export:'导出账号'};const title=computed(()=>labels[props.mode]);const payload=ref(''),realm=ref(props.mode==='create'?'cn':''),label=ref(props.item?.label||''),note=ref(''),token=ref(''),enabled=ref(props.item?.enabled??true),busy=ref(false),loading=ref(false),error=ref(''),confirmed=ref(false)
onMounted(async()=>{if(props.mode==='edit'&&props.item){loading.value=true;try{const a=await detail(props.item.id);note.value=a.note||''}catch(e){error.value=message(e)}finally{loading.value=false}}});async function picked(e:Event){const el=e.target as HTMLInputElement;const file=el.files?.[0];if(!file)return;if(file.size>8*1024*1024){error.value='每次直接导入最多 8 MiB';return}try{payload.value=await file.text();error.value=''}catch{error.value='读取文件失败'}}
async function submit(){busy.value=true;error.value='';try{switch(props.mode){case 'import':{let data:unknown;const s=payload.value.trim();if(!s)throw Error('请输入账号 JSON 或 token');if(/^[{["]/.test(s)){try{data=JSON.parse(s) as unknown}catch{throw Error('JSON 格式无效')}}else{data=s}const r=await importAccounts(data,realm.value);payload.value='';emit('saved','已导入 '+r.imported+' 个账号');break}case 'create':await importAccounts({label:label.value,access_token:token.value},realm.value);token.value='';emit('saved','账号已保存');break;case 'edit':if(!props.item)return;await update(props.item.id,{label:label.value,note:note.value,enabled:enabled.value});emit('saved','账号已更新');break;case 'delete':if(!props.item)return;await remove(props.item.id);emit('saved','账号已删除');break;case 'export':{if(!confirmed.value)return;const f=await download({realm:props.realmFilter,q:props.query});const url=URL.createObjectURL(f.blob),a=document.createElement('a');a.href=url;a.download=f.name;a.click();setTimeout(()=>URL.revokeObjectURL(url),30000);emit('saved','已导出当前筛选结果');break}}}catch(e){error.value=message(e)}finally{busy.value=false}}
</script>
<template><Modal :title="title" :busy="busy" @close="emit('close')"><form @submit.prevent="submit"><template v-if="mode==='create'||mode==='edit'"><label>账号名称<input v-model.trim="label" maxlength="128" required/></label><label v-if="mode==='create'">访问凭证<input v-model.trim="token" type="password" autocomplete="off" required/></label><template v-else><label>备注<textarea v-model="note" :disabled="loading"/></label><label class="check"><input v-model="enabled" type="checkbox"/>启用账号</label></template></template><template v-if="mode==='import'"><label>选择文件<input type="file" accept=".json,application/json,text/plain" @change="picked"/></label><label>账号 JSON 或 token<textarea v-model="payload" class="mono" autocomplete="off" spellcheck="false" required/></label></template><label v-if="mode==='import'||mode==='create'">所属号池<select v-model="realm"><option v-if="mode==='import'" value="">自动识别</option><option value="cn">国内版</option><option value="intl">国际版</option></select></label><p v-if="mode==='delete'">确认删除「{{item?.label}}」的账号文件？此操作无法撤销。</p><template v-if="mode==='export'"><p>备份包含明文访问凭证和出口代理的用户名、密码。请只保存在受信任的位置。</p><label class="check"><input v-model="confirmed" type="checkbox" required/>我已了解，导出当前筛选结果</label></template><p v-if="error" class="error" role="alert">{{error}}</p><div class="actions end"><button type="button" :disabled="busy" @click="emit('close')">取消</button><button class="primary" :disabled="busy||loading||(mode==='export'&&!confirmed)"><Upload v-if="mode==='import'"/><Download v-else-if="mode==='export'"/><Trash2 v-else-if="mode==='delete'"/><Save v-else/>{{busy?'处理中':mode==='delete'?'确认删除':mode==='export'?'确认导出':mode==='import'?'开始导入':'保存'}}</button></div></form></Modal></template>
<style scoped>.check{display:flex;align-items:center;gap:var(--space-2)}.check input{width:18px;min-height:18px;accent-color:var(--md-primary)}</style>
